<?php
require __DIR__.'/auth.php'; require_role(['ADMIN','OPERATOR']);
$api=rtrim(getenv('MONITOR_API_URL')?:'http://api:3000','/');
function api_json(string $method,string $path,?array $body=null):array{global $api;$ch=curl_init($api.$path);$o=[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>10,CURLOPT_CUSTOMREQUEST=>$method,CURLOPT_HTTPHEADER=>['Accept: application/json','Content-Type: application/json']];if($body!==null)$o[CURLOPT_POSTFIELDS]=json_encode($body);curl_setopt_array($ch,$o);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);return ['code'=>$code,'data'=>json_decode($raw?:'{}',true)?:[]];}
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';if($action==='delete_dep')api_json('DELETE','/api/v1/dependencies/'.(int)$_POST['id']);elseif($action==='delete_maint')api_json('DELETE','/api/v1/maintenance/'.(int)$_POST['id']);elseif($action==='add_dep')api_json('POST','/api/v1/dependencies',['parent_host_id'=>(int)$_POST['parent_host_id'],'child_host_id'=>(int)$_POST['child_host_id']]);elseif($action==='add_maint')api_json('POST','/api/v1/maintenance',['host_id'=>($_POST['host_id']??'')!==''?(int)$_POST['host_id']:null,'name'=>trim($_POST['name']),'starts_at'=>$_POST['starts_at'],'ends_at'=>$_POST['ends_at']]);header('Location: admin_infrastructure.php');exit;}
$hosts=api_json('GET','/api/v1/hosts')['data'];$deps=api_json('GET','/api/v1/dependencies')['data'];$maint=api_json('GET','/api/v1/maintenance')['data'];
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Infrastructure Administration</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="index.php">Monitoring Admin</a><a class="btn btn-outline-light btn-sm" href="index.php">Dashboard</a></div></nav><main class="container-fluid p-4"><h2 class="mb-4">Infrastructure Administration</h2><div class="row g-4"><div class="col-lg-6"><div class="card"><div class="card-header fw-semibold">Add Dependency</div><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="add_dep"><div class="mb-2"><label class="form-label">Parent / Root Cause</label><select class="form-select" name="parent_host_id" required><?php foreach($hosts as $h):?><option value="<?=e($h['id'])?>"><?=e($h['name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Child / Dependent</label><select class="form-select" name="child_host_id" required><?php foreach($hosts as $h):?><option value="<?=e($h['id'])?>"><?=e($h['name'])?></option><?php endforeach;?></select></div><button class="btn btn-primary">Create dependency</button></form></div></div><div class="card mt-3"><div class="card-header">Current Dependencies</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Parent</th><th>Child</th><th></th></tr></thead><tbody><?php foreach($deps as $d):?><tr><td><?=e($d['parent_name'])?></td><td><?=e($d['child_name'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete_dep"><input type="hidden" name="id" value="<?=e($d['id'])?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-lg-6"><div class="card"><div class="card-header fw-semibold">Maintenance Window</div><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="add_maint"><div class="mb-2"><label class="form-label">Name</label><input class="form-control" name="name" required></div><div class="mb-2"><label class="form-label">Host (blank = all)</label><select class="form-select" name="host_id"><option value="">All hosts</option><?php foreach($hosts as $h):?><option value="<?=e($h['id'])?>"><?=e($h['name'])?></option><?php endforeach;?></select></div><div class="row"><div class="col"><label class="form-label">Start</label><input class="form-control" type="datetime-local" name="starts_at" required></div><div class="col"><label class="form-label">End</label><input class="form-control" type="datetime-local" name="ends_at" required></div></div><button class="btn btn-primary mt-3">Create maintenance</button></form></div></div><div class="card mt-3"><div class="card-header">Maintenance Windows</div><div class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>Name</th><th>Host</th><th>Start</th><th>End</th><th></th></tr></thead><tbody><?php foreach($maint as $m):?><tr><td><?=e($m['name'])?></td><td><?=e($m['host_name']??'ALL')?></td><td><?=e($m['starts_at'])?></td><td><?=e($m['ends_at'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete_maint"><input type="hidden" name="id" value="<?=e($m['id'])?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div></main></body></html>
